sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float start;
uniform float duration;
uniform float intensity;
uniform float block;
uniform float decay;
uniform float glitch;
uniform float bloom;

float hash(float2 p) { return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453); }

half4 main(float2 xy) {
    half4 plain = image.eval(xy);
    float into = time - start;
    if (into < 0.0 || into >= duration) { return plain; }
    float steps = floor(into * 15.0) + 1.0;
    float b = max(block, 2.0);
    float2 cell = floor(xy / b);
    float2 region = floor(cell / 4.0);
    float2 dir = float2(hash(region + 3.7), hash(region + 9.1)) * 2.0 - 1.0;
    dir += (float2(hash(cell + 1.1), hash(cell + 2.2)) - 0.5) * 0.6;
    float moving = step(0.3, hash(region + 5.5));
    float keep = pow(1.0 - clamp(decay, 0.0, 1.0), steps);
    float grow = steps * (1.0 + bloom * steps * 0.05);
    float2 shift = dir * moving * intensity * b * 0.15 * grow * keep;
    float2 lo = float2(0.5);
    float2 hi = max(size - 0.5, lo);
    half4 moved = image.eval(clamp(xy - shift, lo, hi));
    half4 trail = (image.eval(clamp(xy - shift * 0.66, lo, hi)) + image.eval(clamp(xy - shift * 0.33, lo, hi))) * 0.5;
    half4 c = mix(moved, trail, 0.35);
    float g = hash(cell + float2(steps * 7.13, steps * 3.71));
    if (g < glitch * 0.3) {
        half4 r = image.eval(clamp(xy - shift + float2(b * 0.5, 0.0), lo, hi));
        c = half4(min(r.r, max(c.a, r.a)), c.g, c.b * 0.8, max(c.a, r.a));
    }
    return c;
}
